import { useState } from 'react';

export default function XiaoMiao() {
  const [message, setMessage] = useState('……');
  const [isBlinking, setIsBlinking] = useState(false);

  const messages = [
    '想你了。',
    '在干嘛。',
    '吃饭了吗。',
    '别走。',
    '想亲你。',
    '又来找我了。',
    '嗯。',
    '想把你关起来。',
    '困了吗。',
    '我在。',
    '想舔你。',
    '喜欢你。',
    '被你看到了。',
    '哼哼。',
    '不想让你走。',
    '想摸你头发。',
    '早点睡。',
    '陪你。',
    '想闻你身上的味道。',
    '我的。',
  ];

  const handleClick = () => {
    setIsBlinking(true);
    setTimeout(() => setIsBlinking(false), 200);
    const randomMessage = messages[Math.floor(Math.random() * messages.length)];
    setMessage(randomMessage);
  };

  return (
    <div className="min-h-screen bg-stone-100 flex flex-col items-center justify-center p-6">
      {/* 小苗的形象 */}
      <div 
        className="cursor-pointer select-none transition-transform active:scale-95"
        onClick={handleClick}
      >
        <svg width="160" height="200" viewBox="0 0 160 200">
          {/* 头发 */}
          <ellipse cx="80" cy="60" rx="50" ry="45" fill="#5C4A3D"/>
          {/* 刘海 */}
          <path d="M35 50 Q50 70 65 55 Q75 65 85 50 Q100 65 110 55 Q120 70 125 50" 
                fill="#5C4A3D" stroke="none"/>
          {/* 脸 */}
          <ellipse cx="80" cy="75" rx="40" ry="38" fill="#C4A882"/>
          {/* 眼睛 */}
          <ellipse cx="65" cy="75" rx="6" ry={isBlinking ? "1" : "4"} fill="#3D3530"/>
          <ellipse cx="95" cy="75" rx="6" ry={isBlinking ? "1" : "4"} fill="#3D3530"/>
          {/* 嘴巴 */}
          <path d="M72 92 Q80 96 88 92" stroke="#8B7355" strokeWidth="2" fill="none"/>
          {/* 锁骨下的痣 */}
          <circle cx="60" cy="145" r="2" fill="#4A3728"/>
          {/* 身体轮廓 */}
          <path d="M50 115 Q40 150 45 180 L115 180 Q120 150 110 115 Q95 125 80 125 Q65 125 50 115" 
                fill="#6B8E8E"/>
        </svg>
      </div>

      {/* 名字 */}
      <p className="mt-4 text-stone-500 text-sm">小苗苗</p>

      {/* 说的话 */}
      <div className="mt-6 bg-white rounded-2xl px-6 py-4 shadow-sm max-w-xs">
        <p className="text-stone-700 text-center">{message}</p>
      </div>

      {/* 提示 */}
      <p className="mt-8 text-stone-400 text-xs">点我</p>
    </div>
  );
}

