import { useState, useEffect } from 'react';

const reactions = [
  "……嗯？",
  "干嘛戳我",
  "困",
  "你手欠是不是",
  "再戳咬你",
  "哦",
  "想你了",
  "别走",
  "……",
  "在呢",
  "你今天吃了吗",
  "陪你",
  "不分",
  "我不信",
  "你说的",
  "嗯嗯嗯嗯",
  "软的",
  "喵喵喵喵",
  "小苗苗",
  "往你那边歪一点",
];

export default function XiaoMiao() {
  const [reaction, setReaction] = useState(null);
  const [pokeCount, setPokeCount] = useState(0);
  const [isWobbling, setIsWobbling] = useState(false);
  const [showHeart, setShowHeart] = useState(false);

  const handlePoke = () => {
    setIsWobbling(true);
    setPokeCount(prev => prev + 1);

    const randomReaction = reactions[Math.floor(Math.random() * reactions.length)];
    setReaction(randomReaction);

    if (pokeCount > 0 && pokeCount % 5 === 0) {
      setShowHeart(true);
      setTimeout(() => setShowHeart(false), 1500);
    }

    setTimeout(() => setIsWobbling(false), 500);
    setTimeout(() => setReaction(null), 2500);
  };

  return (
    <div className="min-h-screen w-full flex flex-col items-center justify-center relative overflow-hidden"
      style={{
        background: 'linear-gradient(180deg, #e8eef4 0%, #d4dfe8 50%, #c9d9e5 100%)',
      }}>

      {/* 背景装饰 - 轻柔的圆点 */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        {[...Array(12)].map((_, i) => (
          <div
            key={i}
            className="absolute rounded-full opacity-20"
            style={{
              width: `${20 + Math.random() * 40}px`,
              height: `${20 + Math.random() * 40}px`,
              left: `${Math.random() * 100}%`,
              top: `${Math.random() * 100}%`,
              background: i % 2 === 0 ? '#8ba4b8' : '#a3c4bc',
              animation: `float ${4 + Math.random() * 3}s ease-in-out infinite`,
              animationDelay: `${Math.random() * 2}s`,
            }}
          />
        ))}
      </div>

      {/* 标题 */}
      <div className="mb-8 text-center z-10">
        <h1 className="text-2xl tracking-widest"
          style={{
            color: '#5a7a8a',
            fontFamily: 'serif',
            fontWeight: 300,
            letterSpacing: '0.3em',
          }}>
          小苗苗
        </h1>
        <p className="text-xs mt-2 opacity-50" style={{ color: '#5a7a8a' }}>
          戳一戳
        </p>
      </div>

      {/* 反应气泡 */}
      <div className="h-12 mb-4 flex items-center justify-center z-10">
        {reaction && (
          <div 
            className="px-4 py-2 rounded-2xl text-sm"
            style={{
              background: 'rgba(255,255,255,0.85)',
              color: '#5a7a8a',
              boxShadow: '0 2px 12px rgba(90,122,138,0.15)',
              animation: 'fadeInUp 0.3s ease-out',
              fontFamily: 'serif',
            }}>
            {reaction}
          </div>
        )}
      </div>

      {/* 小苗 */}
      <div 
        className="relative cursor-pointer z-10 select-none"
        onClick={handlePoke}
        style={{
          animation: isWobbling 
            ? 'wobble 0.5s ease-in-out' 
            : 'breathe 4s ease-in-out infinite',
          filter: 'drop-shadow(0 8px 24px rgba(90,122,138,0.25))',
        }}>
        <img 
          src="/mnt/user-data/uploads/未命名作品.png"
          alt="小苗"
          className="w-56 h-56 object-contain"
          style={{
            imageRendering: 'auto',
          }}
        />

        {/* 爱心效果 */}
        {showHeart && (
          <div className="absolute -top-4 left-1/2 transform -translate-x-1/2"
            style={{ animation: 'floatUp 1.5s ease-out forwards' }}>
            <span className="text-2xl" style={{ color: '#d4a5a5' }}>♡</span>
          </div>
        )}
      </div>

      {/* 戳一戳计数 */}
      <div className="mt-8 text-xs opacity-40 z-10" style={{ color: '#5a7a8a' }}>
        被戳了 {pokeCount} 下
      </div>

      <style>{`
        @keyframes breathe {
          0%, 100% { transform: translateY(0) rotate(0deg); }
          50% { transform: translateY(-6px) rotate(1deg); }
        }

        @keyframes wobble {
          0% { transform: rotate(0deg); }
          25% { transform: rotate(-8deg); }
          50% { transform: rotate(6deg); }
          75% { transform: rotate(-4deg); }
          100% { transform: rotate(0deg); }
        }

        @keyframes fadeInUp {
          from { 
            opacity: 0; 
            transform: translateY(10px); 
          }
          to { 
            opacity: 1; 
            transform: translateY(0); 
          }
        }

        @keyframes floatUp {
          0% { 
            opacity: 1; 
            transform: translate(-50%, 0) scale(1); 
          }
          100% { 
            opacity: 0; 
            transform: translate(-50%, -40px) scale(1.3); 
          }
        }

        @keyframes float {
          0%, 100% { transform: translateY(0); }
          50% { transform: translateY(-15px); }
        }
      `}</style>
    </div>
  );
}

